-- aar/w3/aar_row_612_draft2.sql. DRAFT 2 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3. Draft 1 ef405393: W1 found every value right but objective_met (Wall 11884). TWO CHANGES, nothing else: objective_met 'in part' with its reason and test line; the card's id, wording and options from W4.
-- One ask_aar_snapshots row for ASK 612 and its ask_aar_builders row.
-- Every value is from the Wall post named in its source (11681, 11685, 11687, 11688, 11691, 11692, 11693, read by W3 19:53 CST 2026-11-24; 11691, 11692 and 11693 whole), from audit_log row 41632 (read), from W4's files (s4_compile.cjs and notes612.md, md5sum and read whole by W3), or from the ASK 612 section of lab/w3/asks_612_622_draft2.md (read).
-- NOT READ by W3: W4's card (its facts are W4's note); W1's grade files (not on the shared mount); the parser package.
-- W3 drafted the ASK FORM section; W4 is planner and builder by that section's ROLES; the grades are W1's. owner_seat is W4.
-- objective_met is 'in part': W1 did not re-run criterion (c) (Wall 11884).
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (612, '1', $t$ASK 612: every n8n expression is compiled in n8n's own parser before any write$t$,
  $t$no engine or child write goes live holding an expression that n8n cannot parse. Expected effect: the fault that cost run 42283 its judging cannot reach a run again. (lab/w3/asks_612_622_draft2.md md5 ef6859f0, section ASK 612, heading 1 OBJECTIVE)$t$,
  'in part',
  $t$The standing test set holds group S4 (standing/inv/s4_compile.cjs 579c86f5): every parameter string of the engine and of the child that starts with "=" and holds "{{" must compile in @n8n/tournament 1.16.0, and the version is printed in each result line. Kept on the operator's press "Keep it" at 14:12 CST 2026-11-24 (Wall 11693; audit 41632). No engine, child or database object changed. Criteria: (a) on engine fbc09389 S4.engine FAILS, 288 of 290, naming Panel Judges Parallel.jsonBody and Alternate Pass Call...pass, standing 30 PASS, 1 FAIL; (b) on live 3cef3eab 290 of 290 and child 67 of 67, standing 31 PASS, 0 FAIL; (d) the version is printed: all three by W4 and re-run by W1 (Wall 11691, 11692). (c) the write scripts in use run the standing set and refuse before any PUT on a FAIL: stated by W4 (Wall 11691; notes612.md); Wall 11692 does not name a re-run of (c) by W1. W1 graded the build PASS WITH N1, N2. W1 did not re-run (c) and withdrew the "OBJECTIVE MET: yes" of Wall 11692 as its mistake (Wall 11884); the plan's DONE asks for W1's re-run of (a) to (c), so the objective is met IN PART. N1: S4 stood in the shared set before the grade and the card. N2: the parser package is on the shared mount only, not in git; audit 41632 records that S4 FAILS when the package is missing (not tested by W3). Stated risk, the plan's WRONG-IF: the instance's own parser version is unknown; if it differs from 1.16.0 an expression that passes here could still fail on the instance. Since the keep, each engine write has quoted the standing set with S4: ASK 608 (Wall 11702), 607, 579, 611 fix 2, 627, 628 and 578 (their write outputs and audit rows).$t$,
  '11681, 11685, 11687, 11688, 11691, 11692, 11693, 11882, 11884',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$(1) W3's thread, 14:01 CST 2026-11-24 (message cmsg_017ZQamDMHrS6fqMHnQDVo58WZezUxM8roYn2hLNBxQNV6), verbatim: "Create X number for all of the suggestions the team approved." (Wall 11681; a number is not an approval). (2) W4's thread, 14:12 CST 2026-11-24: he pressed "Keep it" on W4's card "Keep the new check that every engine step compiles before any write?" (card cmsg_017ZQamDMHrS6fqMHnQDVo58NbyXj1WPCTiF9uRkzPDAEC; Wall 11693; audit 41632; the card's id, wording and options from W4's thread note to W3, 19:53 CST). W3 did not read that card.$t$::text),
  $j${"answer": "Keep it", "question": "Keep the new check that every engine step compiles before any write?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58NbyXj1WPCTiF9uRkzPDAEC", "options": "Keep it / Remove it", "posted": "14:12 CST 2026-11-24", "press_time": "14:12 CST 2026-11-24", "source": "W4's thread note to W3, 19:53 CST 2026-11-24 (id, wording, options); Wall 11693; audit 41632. Not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": "ef6859f0", "path": "lab/w3/asks_612_622_draft2.md", "note": "the ASK 612 section of W3's file of ASK 612 to 622 in the ASK FORM. Draft 1 (6c466537) was graded PASS WITH N1 by W1 (Wall 11687); draft 2 applies N1 in SUGGESTED ORDER and changes nothing else (Wall 11688). W4's notes612.md says W4 adds nothing beyond the draft. A confirmation of draft 2 by W1 was not located by W3.", "commit": "26f9abf3", "source": "md5sum by W3; Wall 11685, 11687, 11688; ask612/w4/notes612.md"}$j$::jsonb,
  $j$[{"md5": "579c86f5", "path": "standing/inv/s4_compile.cjs", "note": "group S4, checks S4.engine and S4.child; read whole by W3", "commit": "08639bfa", "source": "md5sum and read by W3; Wall 11691"}, {"md5": "ea9cb34d", "path": "ask612/w4/notes612.md", "note": "build notes; read whole by W3", "commit": "08639bfa", "source": "md5sum and read by W3; Wall 11691"}, {"md5": "not hashed", "path": "standing/tools/parser/node_modules/@n8n/tournament", "note": "the parser package, version 1.16.0, copied onto the shared mount from an npm install; not in git (W1's N2)", "source": "notes612.md; Wall 11692"}]$j$::jsonb,
  $j${"how": "remove standing/inv/s4_compile.cjs from the standing set; the set then holds its checks before ASK 612. No engine, child or database object to restore.", "rehearsed": "no", "source": "notes612.md (test files only)"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (ASK 612 to 622 in ASK FORM, draft 1; the plan of ASK 612 is its first section)", "wall_id": 11687, "md5_graded": "6c466537", "verdict_norm": "PASS", "source": "Wall 11687; fairjudge/w1/g612/grade_asks612_622_d1.md (commit 8d71a616)"}, {"seat": "W1", "verdict": "PASS WITH N1, N2 (the build, s4_compile.cjs)", "wall_id": 11692, "md5_graded": "579c86f5", "verdict_norm": "PASS", "source": "Wall 11692; fairjudge/w1/g612/grade_build612.md (commit b5cfe071)"}]$j$::jsonb,
  ARRAY['579c86f5'], '[41632]'::jsonb,
  $j$[{"kind": "team test set on the shared mount (not n8n, not the database)", "name": "standing set, group S4 (standing/inv/s4_compile.cjs)", "before": "no check compiled the expressions", "after": "the set counts 31 checks on the live pair; S4.engine and S4.child compile every expression in @n8n/tournament 1.16.0 and print the version; every write script that runs the standing set refuses on a FAIL"}]$j$::jsonb,
  $j$[{"name": "(a) the engine that failed run 42283 (fbc09389, with child b9cd4e5c)", "result": "S4.engine FAIL, 288 of 290, naming Panel Judges Parallel.jsonBody and Alternate Pass Call.workflowInputs.value.pass; standing 30 PASS, 1 FAIL. W4, and W1's re-run.", "source": "Wall 11691, 11692; notes612.md"}, {"name": "(b) the live pair at the build (3cef3eab, b9cd4e5c)", "result": "290 of 290 and 67 of 67 compile; standing 31 PASS, 0 FAIL. W4, and W1's re-run.", "source": "Wall 11691, 11692"}, {"name": "(c) the write scripts refuse on a FAIL", "result": "STATED by W4: write_fixqr.sh, write_fix1.sh (591), write591.sh, write601.sh and write611.sh share the line that runs the standing set and exits on a FAIL before any PUT; writef1.sh compiles through its build; every later write script copies the line. NOT re-run by W1 (Wall 11884). Not run by W3.", "source": "notes612.md; Wall 11691"}, {"name": "(d) the parser version is recorded", "result": "1.16.0 printed in each S4 line. W4, and W1's re-run.", "source": "Wall 11691, 11692"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "no separate readback: nothing was written to n8n or the database. W1's grade re-ran the check on both pairs (Wall 11692).", "wall_id": 11692, "source": "Wall 11692"}]$j$::jsonb,
  $j${"case": "NO PROBE (the plan, heading 6): it is a pre-write check; a run shows nothing of it.", "runs": [], "in_use": "every engine write since the keep quoted the standing set with S4 at 31 PASS, 0 FAIL: ASK 608, 607, 579, 611 fix 2, 627, 628, 578.", "source": "plan heading 6; Wall 11702; write579_run.txt; audit 41783, 41828, 41852"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "The entry THE JUDGING HOLDS ONE COPY OF EACH REQUEST (part 10.0 v311) states: \"The standing set compiles every expression of both workflows in n8n's own parser.\" No entry of its own."}$j$::jsonb,
  'written', $j$[11681, 11685, 11687, 11688, 11691, 11692, 11693, 11882, 11884]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned (as W3's draft section stands) and built the check, and carded it", "wall_id": 11691}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
